export function introspectBuilder(
  builder: (yargs: Argv) => Argv
): { aliases: Map<string, string[]> } | null {
  try {
    // Lazily require yargs so this module can be imported in environments where
    // yargs is not needed, and to get a fresh instance to configure.
    const yargsFactory = require('yargs');
    const instance: Argv = yargsFactory([]);
    const configured = builder(instance);
    const options = (configured as any).getOptions();

    const aliasRecord: Record<string, string[]> = options?.alias ?? {};
    const keyRecord: Record<string, boolean> = options?.key ?? {};

    // Any name that appears as an alias of another option is not canonical.
    const aliasValues = new Set<string>(
      Object.values(aliasRecord).flat() as string[]
    );

    const aliases = new Map<string, string[]>();
