 * Parses a `process.argv`-style array for shell completion.
 *
 * Strips the first two entries (the node runtime and the nx binary path), then
 * strips a leading `nx` script-name token if present. Returns the remaining
 * shell tokens along with the token currently being completed (`current`) and
 * the token before it (`previousToken`).
 *
 * @returns `null` when no user-supplied tokens remain after stripping.
 */
export function parseCompletionArgs(
  argv: string[]
): { tokens: string[]; current: string; previousToken: string } | null {
  // Strip the node runtime and the nx binary path.
  let tokens = argv.slice(2);

  // Strip a leading `nx` script-name token if the shell included it.
  if (tokens.length > 0 && tokens[0] === 'nx') {
    tokens = tokens.slice(1);
  }

  if (tokens.length === 0) {
    return null;
  }

  const current = tokens[tokens.length - 1];
  const previousToken = tokens.length > 1 ? tokens[tokens.length - 2] : '';

  return { tokens, current, previousToken };
}
