 * Registry of completion metadata keyed by the space-separated command path
 * (e.g. `'show target'`).
 */
const registry = new Map<string, CompletionMetadata>();

/**
 * Registers completion metadata for a command path. The path is a
 * space-separated string of command tokens (e.g. `'show target'`).
 */
export function registerCompletion(
  path: string,
  metadata: CompletionMetadata
): void {
  registry.set(path, metadata);
}

function isFlag(token: string): boolean {
  return token.startsWith('--');
}

/**
 * Searches the registry for the longest registered path that matches a prefix
 * of the given tokens array. The final token is treated as the value currently
 * being completed and is not considered part of the command path. Flags (tokens
 * starting with `--`) halt the prefix walk.
 *
 * @returns the matching metadata and the `positionalIndex` (count of non-flag
 * tokens typed beyond the matched path), or `null` when no path matches.
 */
export function findCompletionMetadata(
  tokens: string[]
): { metadata: CompletionMetadata; positionalIndex: number } | null {
  if (!tokens || tokens.length === 0) {
    return null;
  }

  // The last token is the partial value currently being typed; it does not
  // participate in path matching or positional counting.
  const completed = tokens.slice(0, tokens.length - 1);

  // Build the candidate command path from leading non-flag tokens.
  const pathCandidate: string[] = [];
  for (const token of completed) {
    if (isFlag(token)) {
      break;
    }
    pathCandidate.push(token);
  }

  // Find the longest registered path that is a prefix of the candidate.
  let bestPath: string | null = null;
  let bestLength = -1;
  for (const registeredPath of registry.keys()) {
    const parts = registeredPath.split(' ');
    if (parts.length > pathCandidate.length) {
      continue;
    }
    let matches = true;
    for (let i = 0; i < parts.length; i++) {
      if (parts[i] !== pathCandidate[i]) {
        matches = false;
        break;
      }
    }
    if (matches && parts.length > bestLength) {
      bestLength = parts.length;
      bestPath = registeredPath;
    }
  }

  if (bestPath === null) {
    return null;
  }

  const matchedLength = bestPath.split(' ').length;
  let positionalIndex = 0;
  for (let i = matchedLength; i < completed.length; i++) {
    if (!isFlag(completed[i])) {
      positionalIndex++;
    }
  }

  return { metadata: registry.get(bestPath)!, positionalIndex };
}

/**
 * Looks up the flag completion handler for a given flag name in a metadata
 * object. Returns `null` if metadata is `null` or the flag has no registered
 * handler.
 */
export function findFlagCompletion(
  metadata: CompletionMetadata | null,
  flag: string
): CompletionFn | null {
  if (!metadata || !metadata.flags) {
    return null;
  }
  return metadata.flags[flag] ?? null;
}

/**
 * Resolves completion candidates for the given tokens.
 *
 * Flag dispatch takes precedence over positional dispatch: if `previousToken`
 * starts with `--` and a flag handler is registered, the handler is called; if
 * `previousToken` starts with `--` but no handler is registered, returns `[]`
 * (no fallthrough to positionals). Otherwise dispatches to the positional
 * completer at the computed `positionalIndex` (calling `complete` or filtering
 * `choices` by prefix).
 *
 * @returns `null` for empty tokens, no metadata match, or a `positionalIndex`
 * beyond the declared positionals.
 */
export function resolveCompletion(
  tokens: string[],
  current: string,
  previousToken: string
): string[] | null {
  if (!tokens || tokens.length === 0) {
    return null;
  }

  const match = findCompletionMetadata(tokens);

  // Flag dispatch takes precedence over positional dispatch.
  if (isFlag(previousToken)) {
    const flagName = previousToken.replace(/^--/, '');
    const handler = findFlagCompletion(match?.metadata ?? null, flagName);
    if (handler) {
      return handler(current, tokens);
    }
    // A flag was typed but has no registered handler — do not fall through.
    return [];
  }

  if (!match) {
    return null;
  }

  const { metadata, positionalIndex } = match;
  const positionals = metadata.positionals ?? [];
  if (positionalIndex >= positionals.length) {
    return null;
  }

  const positional = positionals[positionalIndex];
  if (positional.complete) {
    return positional.complete(current, tokens);
  }
  if (positional.choices) {
    return positional.choices.filter((choice) => choice.startsWith(current));
  }
