import { resolveCompletion } from './metadata';
// Ensure completion metadata is registered before we attempt to resolve.
import './registrations';

/**
 * Fast-path completion entry point.
 *
 * Parses `argv` using {@link parseCompletionArgs}. If no tokens are found,
 * returns `false`. Calls {@link resolveCompletion} with the parsed tokens,
 * current, and previousToken. If it returns `null` (no registered metadata
 * matches), returns `false`. If it returns a string array (possibly empty),
 * writes each candidate on its own line to stdout via `console.log` and returns
 * `true`.
 */
export function tryValueCompletion(argv: string[]): boolean {
  const parsed = parseCompletionArgs(argv);
  if (!parsed) {
    return false;
  }

  const { tokens, current, previousToken } = parsed;
  const completions = resolveCompletion(tokens, current, previousToken);
  if (completions === null) {
    return false;
  }

  for (const completion of completions) {
    // eslint-disable-next-line no-console
    console.log(completion);
  }
  return true;
}
