import { handleErrors } from '../../utils/handle-errors';

/**
 * `nx completion <shell>` prints a shell completion installation script to
 * stdout. Supported shells: bash, zsh, fish, powershell.
 */
export const yargsCompletionCommand: CommandModule = {
  command: 'completion [shell]',
  describe: 'Generate a shell completion script for nx.',
  builder: (yargs) =>
    yargs.positional('shell', {
      describe: 'The shell to generate a completion script for.',
      type: 'string',
      choices: ['bash', 'zsh', 'fish', 'powershell'] as const,
    }),
  handler: async (args) => {
    const exitCode = await handleErrors(false, async () => {
      const { generateScript } = await import('./scripts');
      const shell = (args.shell as
        | 'bash'
        | 'zsh'
        | 'fish'
        | 'powershell'
        | undefined) ?? detectShell();
      const script = await generateScript(shell);
      // eslint-disable-next-line no-console
      console.log(script);
    });
    process.exit(exitCode);
  },
};

function detectShell(): 'bash' | 'zsh' | 'fish' | 'powershell' {
  const shell = process.env.SHELL ?? '';
  if (shell.includes('zsh')) {
    return 'zsh';
  }
  if (shell.includes('fish')) {
    return 'fish';
  }
  if (shell.includes('pwsh') || shell.includes('powershell')) {
    return 'powershell';
  }
  return 'bash';
}
