denCount > 0) {\n        flakyRows.push(`  ${hiddenCount} more...`);\n      }\n      output.warn({\n        title: `Nx detected ${\n          this.flakyTasks.length === 1\n            ? 'a flaky task'\n            : `${this.flakyTasks.length} flaky tasks`\n        }`,\n        bodyLines: [\n          ,\n          ...flakyRows,\n          ...(isNxCloudUsed(readNxJson())\n            ? []\n            : [\n                '',\n                `Flaky tasks can disrupt your CI pipeline. Automatically retry them with Nx Cloud. Learn more at https://nx.dev/ci/features/flaky-tasks`,\n              ]),\n        ],\n      });\n    }\n  }\n}\n"],"names":["TaskHistoryLifeCycle","getTasksHistoryLifeCycle","tasksHistoryLifeCycle","IS_WASM","LegacyTaskHistoryLifeCycle","startTimings","pendingResults","Map","taskRuns","taskHistory","getTaskHistory","Error","startTasks","tasks","task","id","Date","getTime","endTasks","taskResults","taskResult","set","endCommand","hash","target","code","status","start","startTime","end","endTime","now","cacheable","cache","runs","cacheableHashes","iterator","entries","run","push","recordTaskRuns","flakyTasks","length","getFlakyTasks","isTuiEnabled","printFlakyTasksMessage","MAX_VISIBLE_FLAKY","visibleFlaky","slice","hiddenCount","flakyRows","map","taskRun","get","serializeTarget","project","configuration","output","warn","title","bodyLines","isNxCloudUsed","readNxJson"],"mappings":";;;;wBAA2B;wBAE4B;8BACzB;wBACP;iCACS;6BACY;8BACf;yCAEc;+BAqB9BA;;;eAAAA;;;QAAAA;;;;+BAZGC;;;eAAAA;;;QAAAA;;;;AAFhB,IAAIC;AAEG,SAASD;IAGd,IAAI,CAACC,uBAAuB;QAC1BA,wBAAwB,CAACC,eAAO,GAC5B,IAAIH,yBACJ,IAAII,mDAA0B;IACpC;IAEA,OAAOF;AACT;AAEO,MAAMF;IAOX,aAAc;aANNK,eAAuC,CAAC;aACxCC,iBAAiB,IAAIC;aACrBC,WAAW,IAAID;aACfE,cAAkCC,IAAAA,2BAAc;QAItD,IAAIR,uBAAuB;YACzB,MAAM,IAAIS,MACR;QAEJ;QACAT,wBAAwB,IAAI;IAC9B;IAEAU,WAAWC,KAAa,EAAQ;QAC9B,KAAK,IAAIC,QAAQD,MAAO;YACtB,IAAI,CAACR,YAAY,CAACS,KAAKC,EAAE,CAAC,GAAG,IAAIC,OAAOC,OAAO;QACjD;IACF;IAEA,MAAMC,SAASC,WAAyB,EAAE;QACxC,KAAK,MAAMC,cA