+{"version":3,"sources":["/workspace/repo/packages/nx/src/project-graph/plugins/isolation/messaging.ts"],"sourcesContent":["import type { Serializable } from 'child_process';\nimport type { Socket } from 'net';\nimport type { PluginConfiguration } from '../../../config/nx-json';\nimport type { ProjectGraph } from '../../../config/project-graph';\nimport { serialize } from '../../../daemon/socket-utils';\nimport { MESSAGE_END_SEQ } from '../../../utils/consume-messages-from-socket';\nimport type { LoadedNxPlugin } from '../loaded-nx-plugin';\nimport type {\n  CreateDependenciesContext,\n  CreateMetadataContext,\n  CreateNodesContextV2,\n  PostTasksExecutionContext,\n  PreTasksExecutionContext,\n} from '../public-api';\nimport type {\n  AllMessages,\n  AllResults,\n  DefineMessages,\n  Handlers,\n  MaybePromise,\n  ResultOf,\n  WithResult,\n} from './message-types';\n\n// =============================================================================\n// PLUGIN MESSAGE DEFINITIONS\n// =============================================================================\n\n/**\n * All plugin worker message definitions in one place.\n * Each entry defines:\n * - payload: what the message carries\n * - result (optional): what the response carries\n */\ntype PluginMessageDefs = DefineMessages<{\n  load: {\n    payload: {\n      plugin: PluginConfiguration;\n      root: string;\n      name: string;\n      pluginPath: string;\n      shouldRegisterTSTranspiler: boolean;\n    };\n    result:\n      | {\n          name: string;\n          include?: string[];\n          exclude?: string[];\n          createNodesPattern: string;\n          hasCreateDependencies: boolean;\n          hasProcessProjectGraph: boolean;\n          hasCreateMetadata: boolean;\n          hasPreTasksExecution: boolean;\n          hasPostTasksExecution: boolean;\n          success: true;\n        }\n      | {\n          success: false;\n          error: Error;\n        };\n  };\n\n  createNodes: {\n    payload: {\n      configFiles: string[];\n      context: CreateNodesContextV2;\n    };\n    result:\n      | {\n          success: true;\n          result: Awaited<ReturnType<LoadedNxPlugin['createNodes'][1]>>;\n        }\n      | {\n          success: false;\n          error: Error;\n        };\n  };\n\n  createDependencies: {\n    payload: {\n      context: CreateDependenciesContext;\n    };\n    result:\n      | {\n          dependencies: Awaited<\n            ReturnType<LoadedNxPlugin['createDependencies']>\n          >;\n          success: true;\n        }\n      | {\n          success: false;\n          error: Error;\n        };\n  };\n\n  createMetadata: {\n    payload: {\n      graph: ProjectGraph;\n      context: CreateMetadataContext;\n    };\n    result:\n      | {\n          metadata: Awaited<ReturnType<LoadedNxPlugin['createMetadata']>>;\n          success: true;\n        }\n      | {\n          success: false;\n          error: Error;\n        };\n  };\n\n  preTasksExecution: {\n    payload: {\n      context: PreTasksExecutionContext;\n    };\n    result:\n      | {\n          success: true;\n          mutations: NodeJS.ProcessEnv;\n        }\n      | {\n          success: false;\n          error: Error;\n        };\n  };\n\n  postTasksExecution: {\n    payload: {\n      context: PostTasksExecutionContext;\n    };\n    result:\n      | {\n          success: true;\n        }\n      | {\n          success: false;\n          error: Error;\n        };\n  };\n\n  setWorkerEnv: {\n    payload: Record<string, string>;\n    result:\n      | {\n          success: true;\n        }\n      | {\n          success: false;\n          error: Error;\n        };\n  };\n}>;\n\n// =============================================================================\n// EXPORTED TYPES (derived from PluginMessageDefs)\n// =============================================================================\n\n/** Union of all plugin worker message types */\nexport type PluginWorkerMessage = AllMessage