+{"version":3,"sources":["/workspace/repo/packages/nx/src/command-line/import/utils/ai-output.ts"],"sourcesContent":["/**\n * AI Agent NDJSON Output Utilities for nx import\n *\n * Extends the shared base with import-specific types and builders.\n */\n\nimport {\n  writeAiOutput,\n  logProgress,\n  writeErrorLog,\n  type DetectedPlugin,\n  type NextStep,\n  type UserNextSteps,\n  type PluginWarning,\n} from '../../ai/ai-output';\n\n// Re-export shared utilities for convenience\nexport { writeAiOutput, logProgress, writeErrorLog };\n\n// Import-specific progress stages\nexport type ImportProgressStage =\n  | 'starting'\n  | 'cloning'\n  | 'filtering'\n  | 'merging'\n  | 'detecting-plugins'\n  | 'installing'\n  | 'installing-plugins'\n  | 'complete'\n  | 'error'\n  | 'needs_input';\n\n// Import-specific error codes\nexport type NxImportErrorCode =\n  | 'UNCOMMITTED_CHANGES'\n  | 'CLONE_FAILED'\n  | 'SOURCE_NOT_FOUND'\n  | 'DESTINATION_NOT_EMPTY'\n  | 'INVALID_DESTINATION'\n  | 'FILTER_FAILED'\n  | 'MERGE_FAILED'\n  | 'PACKAGE_INSTALL_ERROR'\n  | 'PLUGIN_INIT_ERROR'\n  | 'UNKNOWN';\n\ninterface ImportOptionInfo {\n  description: string;\n  flag: string;\n  required: boolean;\n}\n\nexport interface ImportNeedsOptionsResult {\n  stage: 'needs_input';\n  success: false;\n  inputType: 'import_options';\n  message: string;\n  missingFields: string[];\n  availableOptions: Record<string, ImportOptionInfo>;\n  exampleCommand: string;\n}\n\nexport interface ImportNeedsPluginSelectionResult {\n  stage: 'needs_input';\n  success: false;\n  inputType: 'plugins';\n  message: string;\n  detectedPlugins: DetectedPlugin[];\n  options: string[];\n  recommendedOption: string;\n  recommendedReason: string;\n  exampleCommand: string;\n  result: {\n    sourceRepository: string;\n    ref: string;\n    source: string;\n    destination: string;\n  };\n}\n\nexport interface ImportSuccessResult {\n  stage: 'complete';\n  success: true;\n  result: {\n    sourceRepository: string;\n    ref: strin