{\n      contents = [contents, file].join('\\n');\n    }\n  });\n  host.write('.gitignore', contents);\n}\n\n// Gets the sanitized contents for nxw.js\nexport function getNxWrapperContents() {\n  return sanitizeWrapperScript(\n    readFileSync(path.join(__dirname, 'nxw.js'), 'utf-8')\n  );\n}\n\n// Gets the contents for the nx bash script\nexport function getShellScriptContents() {\n  return SHELL_SCRIPT_CONTENTS;\n}\n\n// Gets the contents for the nx.bat batch script\nexport function getBatchScriptContents() {\n  return BATCH_SCRIPT_CONTENTS;\n}\n\n// Remove any empty comments or comments that start with `//#: ` or eslint-disable comments.\n// This removes the sourceMapUrl since it is invalid, as well as any internal comments.\nexport function sanitizeWrapperScript(input: string) {\n  const linesToRemove = [\n    // Comments that start with //#\n    '\\\\/\\\\/# .*',\n    // Comments that are empty (often used for newlines between internal comments)\n    '\\\\s*\\\\/\\\\/\\\\s*',\n    // Comments that disable an eslint rule.\n    '\\\\/\\\\/ eslint-disable-next-line.*',\n  ];\n  const regex = `(${linesToRemove.join('|')})$`;\n  return input.replace(new RegExp(regex, 'gm'), '');\n}\n"],"names":["generateDotNxSetup","getBatchScriptContents","getNxWrapperContents","getShellScriptContents","normalizeVersionForNxJson","nxWrapperPath","sanitizeWrapperScript","updateGitIgnore","writeMinimalNxJson","p","path","join","NODE_MISSING_ERR","NPM_MISSING_ERR","BATCH_SCRIPT_CONTENTS","win32","SHELL_SCRIPT_CONTENTS","posix","version","host","FsTree","process","cwd","write","mode","FsConstants","S_IXUSR","S_IRUSR","S_IWUSR","changes","listChanges","printChanges","flushChanges","root","execSync","stdio","encoding","windowsHide","e","stderr","pkg","valid","toString","trimEnd","exists","writeJson","installation","contents","read","forEach","file","includes","readFileSync","__dirname","input","linesToRemove","regex","replace","RegExp"],"mappings":";;;;+BAAyB;oBAC8B;8DACjC;wBACA;sBAOf;sB